//! Kotlin's character rules, for Rust that must treat text exactly as the Kotlin it replaces.
//!
//! Kotlin's `String` is UTF-16, and its `Char` functions (`isLetter`, `uppercaseChar`, ...) look
//! at one UTF-16 unit at a time and answer from `java.lang.Character`. Rust's `char` methods
//! answer differently for some characters: `is_alphabetic` counts Roman numerals such as Ⅻ,
//! `to_uppercase` turns ß into SS where Kotlin keeps ß, and `is_whitespace` counts U+0085 but not
//! the separators U+001C to U+001F. So these functions take a UTF-16 unit and answer from tables
//! generated by asking Java itself, on Android for the library built for Android and on the JVM
//! for the one built for a computer, as the two differ (see `tables`).
//!
//! The text functions at the bottom work on `&[u16]`, the units of a Kotlin `String`.

#![forbid(unsafe_code)]

mod tables;

use tables::TABLES;

// The flag bits in the tables, as tools/JavaChars.java writes them.
const LETTER: u8 = 1;
const DIGIT: u8 = 2;
const LETTER_OR_DIGIT: u8 = 4;
const UPPER: u8 = 8;
const LOWER: u8 = 16;
const SPACE: u8 = 32;
const REGEX_SPACE: u8 = 64;

fn has(unit: u16, flag: u8) -> bool {
    TABLES.flags(unit) & flag != 0
}

/// Kotlin's `Char.isLetter()`: general category L (Lu, Ll, Lt, Lm or Lo).
pub fn is_letter(unit: u16) -> bool {
    has(unit, LETTER)
}

/// Kotlin's `Char.isDigit()`: general category Nd, so not ² or Ⅻ.
pub fn is_digit(unit: u16) -> bool {
    has(unit, DIGIT)
}

/// Kotlin's `Char.isLetterOrDigit()`.
pub fn is_letter_or_digit(unit: u16) -> bool {
    has(unit, LETTER_OR_DIGIT)
}

/// Kotlin's `Char.isUpperCase()`: Lu, and on the JVM also Unicode's Other_Uppercase (such as Ⓐ).
pub fn is_upper_case(unit: u16) -> bool {
    has(unit, UPPER)
}

/// Kotlin's `Char.isLowerCase()`: Ll, and on the JVM also Unicode's Other_Lowercase (such as ª).
pub fn is_lower_case(unit: u16) -> bool {
    has(unit, LOWER)
}

/// Kotlin's `Char.isWhitespace()`: Java's `isWhitespace` or `isSpaceChar`, which takes in the
/// no-break spaces and the separators U+001C to U+001F, but not U+0085.
pub fn is_whitespace(unit: u16) -> bool {
    has(unit, SPACE)
}

/// Whether `\s` in a Kotlin `Regex` matches the unit: ASCII whitespace on the JVM, and all of
/// Unicode's White_Space on Android, whose regex is ICU's.
pub fn is_regex_space(unit: u16) -> bool {
    has(unit, REGEX_SPACE)
}

/// Kotlin's `Char.uppercaseChar()`: one unit to one, so ß stays ß.
pub fn to_upper(unit: u16) -> u16 {
    TABLES.upper(unit)
}

/// Kotlin's `Char.lowercaseChar()`: one unit to one, so İ becomes plain i.
pub fn to_lower(unit: u16) -> u16 {
    TABLES.lower(unit)
}

/// Kotlin's `String.trim()`: without the whitespace ([`is_whitespace`]) at either end.
pub fn trim(text: &[u16]) -> &[u16] {
    let start = text
        .iter()
        .position(|&u| !is_whitespace(u))
        .unwrap_or(text.len());
    let end = text
        .iter()
        .rposition(|&u| !is_whitespace(u))
        .map_or(start, |i| i + 1);
    &text[start..end]
}

/// Kotlin's `String.isBlank()`: empty, or all whitespace ([`is_whitespace`]).
pub fn is_blank(text: &[u16]) -> bool {
    text.iter().all(|&u| is_whitespace(u))
}

/// Whether Kotlin's `text.lowercase() == ascii`, for `ascii` in lower case.
///
/// `lowercase()` maps one unit to one ([`to_lower`]) except for İ, which becomes i and a combining
/// dot, Σ, whose lower case depends on the letters around it, and surrogates; on Android a string
/// with İ or a surrogate is lower-cased by ICU, whose only other change of length is also İ's.
/// None of these ends up in plain ASCII, so a text holding one never matches.
pub fn lower_equals_ascii(text: &[u16], ascii: &str) -> bool {
    debug_assert!(
        !ascii
            .bytes()
            .any(|b| b.is_ascii_uppercase() || !b.is_ascii())
    );
    text.len() == ascii.len()
        && text
            .iter()
            .zip(ascii.bytes())
            .all(|(&u, b)| u != DOTTED_CAPITAL_I && to_lower(u) == u16::from(b))
}

/// İ, whose `lowercase()` is two units.
const DOTTED_CAPITAL_I: u16 = 0x0130;

#[cfg(test)]
mod tests {
    use super::*;

    fn utf16(text: &str) -> Vec<u16> {
        text.encode_utf16().collect()
    }

    fn unit(c: char) -> u16 {
        u16::try_from(u32::from(c)).unwrap()
    }

    #[test]
    fn the_tables_are_well_formed() {
        for tables in [&tables::jvm::TABLES, &tables::android::TABLES] {
            assert_eq!(tables.flag_starts[0], 0);
            assert!(tables.flag_starts.is_sorted_by(|a, b| a < b));
            assert_eq!(tables.flags.len(), tables.flag_starts.len());
            assert!(tables.upper_from.is_sorted_by(|a, b| a < b));
            assert_eq!(tables.upper_to.len(), tables.upper_from.len());
            assert!(tables.lower_from.is_sorted_by(|a, b| a < b));
            assert_eq!(tables.lower_to.len(), tables.lower_from.len());
        }
    }

    /// Every difference between Android's answers and the JVM's is one `tables` explains.
    #[test]
    fn android_differs_from_the_jvm_only_as_explained() {
        let (jvm, android) = (&tables::jvm::TABLES, &tables::android::TABLES);
        for unit in 0..=u16::MAX {
            let (j, a) = (jvm.flags(unit), android.flags(unit));
            // Android's case is the JVM's less Other_Uppercase and Other_Lowercase: never more.
            assert_eq!(a & (UPPER | LOWER) & !j, 0, "{unit:04X}");
            // Android's \s is a superset of the JVM's ASCII.
            assert!(a & REGEX_SPACE != 0 || j & REGEX_SPACE == 0, "{unit:04X}");
            let whitespace_differs = (j ^ a) & SPACE != 0;
            assert_eq!(whitespace_differs, unit == 0x180E, "{unit:04X}");
            let rest = LETTER | DIGIT | LETTER_OR_DIGIT;
            assert_eq!(j & rest, a & rest, "{unit:04X}");
            assert_eq!(jvm.upper(unit), android.upper(unit), "{unit:04X}");
            assert_eq!(jvm.lower(unit), android.lower(unit), "{unit:04X}");
        }
        let lower = |tables: &tables::Tables, c: char| tables.flags(unit(c)) & LOWER != 0;
        let upper = |tables: &tables::Tables, c: char| tables.flags(unit(c)) & UPPER != 0;
        assert!(lower(jvm, 'ª') && !lower(android, 'ª'));
        assert!(upper(jvm, 'Ⅻ') && !upper(android, 'Ⅻ'));
        assert!(lower(android, 'a') && upper(android, 'A'));
        let regex_space = |tables: &tables::Tables, u: u16| tables.flags(u) & REGEX_SPACE != 0;
        for u in [0x85, 0xA0, 0x1680, 0x2007, 0x2028, 0x202F, 0x3000] {
            assert!(regex_space(android, u) && !regex_space(jvm, u), "{u:04X}");
        }
        assert!(!regex_space(android, 0x1C) && !regex_space(android, 0x180E));
    }

    #[test]
    fn regex_space_is_ascii_whitespace_on_the_jvm() {
        let ascii: Vec<u16> = (0..=u16::MAX).filter(|&u| is_regex_space(u)).collect();
        assert_eq!(ascii, [0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20]);
    }

    #[test]
    fn letters_are_category_l_only() {
        for c in ['a', 'Z', 'ß', 'ǅ', 'ʰ', '中', 'ª'] {
            assert!(is_letter(unit(c)), "{c}");
        }
        // Roman numerals are Nl, which Rust's is_alphabetic counts; Java doesn't.
        for c in ['Ⅻ', '1', '²', '\'', '’', ' ', '\u{0301}'] {
            assert!(!is_letter(unit(c)), "{c}");
        }
    }

    #[test]
    fn digits_are_category_nd_only() {
        for c in ['0', '9', '٣', '９'] {
            assert!(is_digit(unit(c)) && is_letter_or_digit(unit(c)), "{c}");
        }
        for c in ['²', '½', 'Ⅻ', 'a'] {
            assert!(!is_digit(unit(c)), "{c}");
        }
        assert!(is_letter_or_digit(unit('a')));
        assert!(!is_letter_or_digit(unit('Ⅻ')));
    }

    #[test]
    fn on_the_jvm_case_counts_other_uppercase_and_lowercase() {
        assert!(is_upper_case(unit('A')) && is_upper_case(unit('Ⓐ')) && is_upper_case(unit('Ⅻ')));
        assert!(is_lower_case(unit('a')) && is_lower_case(unit('ª')) && is_lower_case(unit('ʰ')));
        // Title case is neither.
        assert!(!is_upper_case(unit('ǅ')) && !is_lower_case(unit('ǅ')));
        assert!(!is_upper_case(unit('1')) && !is_lower_case(unit('1')));
    }

    #[test]
    fn whitespace_is_kotlins() {
        for u in [
            0x20, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x1C, 0x1F, 0xA0, 0x1680, 0x2007, 0x202F,
        ] {
            assert!(is_whitespace(u), "{u:04X}");
        }
        for u in [0x3000, 0x2028, 0x2029] {
            assert!(is_whitespace(u), "{u:04X}");
        }
        for u in [0x85, 0x200B, 0xFEFF, 0x00, 0x1B, 0x21] {
            assert!(!is_whitespace(u), "{u:04X}");
        }
    }

    #[test]
    fn case_maps_one_unit_to_one() {
        assert_eq!(to_upper(unit('a')), unit('A'));
        assert_eq!(to_upper(unit('ß')), unit('ß'));
        assert_eq!(to_upper(unit('ǆ')), unit('Ǆ'));
        assert_eq!(to_upper(unit('ᾳ')), 0x1FBC);
        assert_eq!(to_upper(unit('ı')), unit('I'));
        assert_eq!(to_lower(unit('A')), unit('a'));
        assert_eq!(to_lower(unit('İ')), unit('i'));
        assert_eq!(to_lower(0x212A), unit('k')); // the Kelvin sign
        assert_eq!(to_lower(unit('Ⅻ')), unit('ⅻ'));
        assert_eq!(to_lower(0xD801), 0xD801); // a surrogate is left alone
        assert_eq!(to_upper(unit('1')), unit('1'));
    }

    #[test]
    fn trims_kotlins_whitespace() {
        assert_eq!(
            trim(&utf16("\u{A0}\u{1C} hi there\t\u{3000}")),
            utf16("hi there")
        );
        assert_eq!(trim(&utf16("\u{85}hi\u{85}")), utf16("\u{85}hi\u{85}"));
        assert_eq!(trim(&utf16(" \t ")), utf16(""));
        assert_eq!(trim(&[]), [0u16; 0]);
    }

    #[test]
    fn blank_is_empty_or_all_whitespace() {
        assert!(is_blank(&[]));
        assert!(is_blank(&utf16(" \u{A0}\n")));
        assert!(!is_blank(&utf16(" \u{85}")));
    }

    #[test]
    fn compares_lowercase_with_ascii() {
        assert!(lower_equals_ascii(&utf16("New Line"), "new line"));
        assert!(lower_equals_ascii(
            &utf16("QUESTION MAR\u{212A}"),
            "question mark"
        ));
        assert!(!lower_equals_ascii(&utf16("İf"), "if"));
        assert!(!lower_equals_ascii(&utf16("new  line"), "new line"));
        assert!(!lower_equals_ascii(&utf16("newline"), "new line"));
        assert!(lower_equals_ascii(&[], ""));
    }
}
